#!/usr/bin/env python3
# luxarch:guard-cmd hook v2 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Shared: which guard runs a container command, and with what arguments.

A guard image's ENTRYPOINT is the guard, so `docker run <image> --rule x` runs `luxarch --rule x`.
An image's NAME does not say what runs: a test image tagged `luxarch:local-<KEY>-testenv` runs
`python -m pytest`, and an `--entrypoint` override runs whatever it names. So the command is read
as argv, the way the shell will run it (wrappers set aside, a `sh -c` body read by
`_cmdtext.simple_commands`), and a guard runs only where that argv starts it:

  * no command, or one that starts with an option: the entrypoint guard, with those arguments;
  * the guard's own command (`luxarch …`), also through a runner (`uv run`, `poetry run`, …);
  * `python -m <guard>[.cli] …`;
  * `python -c <code> …` whose code calls the guard's `main` (bound by `from <guard>.cli import
    main` or `*`, or `<module>.main` on an imported guard module): its arguments are the literal
    list the call is handed, else the literal list assigned to `sys.argv` once, before the first
    call, else what follows the code.

A word the hook cannot read as a literal (`$ARGS`, `"$@"`, a backtick) where it decides what runs
reads as a run with NO arguments: in the entrypoint guard's arguments, in the program or a wrapper's
words, in the arguments of a guard, a runner, and an interpreter's options, module, code or
script. After a literal program that is known to run nothing (`pytest`, `ruff`, `mypy`, and `python -m` of one of them) it decides
nothing; after any other program it may name the guard, so it reads as a full scan (v2). The
wrappers set aside before the program include `ionice`, `setsid`, `flock <file>` (its `-c` command
read as a shell's), `taskset <mask>` and `chrt <prio>`, and `python -m cProfile|pdb|runpy|trace|…`
is read as the module it runs; `python -m <guard>.<any module>` is the guard. Arguments
that cannot be read (a list built at run time, code that does not parse, `sys.argv`
assigned twice, after the call or changed any other way, `main` bound to another name or handed
on as a value) read as a run with NO arguments: a full scan, so a check judging the run denies it
rather than passing a scan it cannot see. Not read (stated limits): a guard started from a script
file or a module of the repo's own, by `runpy`/`importlib`/`getattr`, or through a name a star
import of another module re-exports.

`selects_rules` reads `--rule` as the CLI does: each value split on commas, empty tokens dropped,
argparse's unambiguous prefixes (`--ru`, `--rul`) accepted; a run left with no token, or whose
value is not a literal, is a full scan.

Python 3.9 and the standard library only, like the hooks that load it.
"""

from __future__ import annotations

import ast
import os
import re

from _cmdtext import SimpleCommand, argv_bodies, simple_commands

_PYTHON = re.compile(r"^python(?:\d+(?:\.\d+)?)?$")
# long interpreter options that take the next word
_PY_VALUED = {"--check-hash-based-pycs"}
_ASSIGNMENT = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*=")
# wrappers that run the rest of the line, with their options that take the next word
_WRAPPERS = {
    "env": {"-u", "-C", "--unset", "--chdir", "-S", "--split-string"},
    "timeout": {"-s", "-k", "--signal", "--kill-after"},
    "nice": {"-n", "--adjustment"},
    "stdbuf": {"-i", "-o", "-e"},
    "exec": {"-a"},
    "nohup": set(),
    "time": set(),
    "command": set(),
    "ionice": {"-c", "-n", "--class", "--classdata"},
    "setsid": set(),
    "flock": {"-w", "--timeout", "-E", "--conflict-exit-code"},
    "taskset": set(),
    "chrt": set(),
    "numactl": set(),
    "caffeinate": set(),
    "unbuffer": set(),
}
# a wrapper's positional words before the command it runs (a duration, a lock file, a mask)
_WRAPPER_POSITIONALS = {"timeout": 1, "flock": 1, "taskset": 1, "chrt": 1}
# modules that run another module or script named in their own arguments
_MODULE_RUNNERS = {"cProfile", "profile", "trace", "pdb", "runpy", "timeit", "coverage"}
# bound to a name: an inline `except (A, B)` formats differently under py314 (PEP 758)
_UNPARSEABLE = (SyntaxError, ValueError)
_FULL: list[str] = []  # a run whose arguments cannot be read: judged as a full scan


_UNREAD = re.compile(r"[$`]")
_RUNNERS = {"uv", "uvx", "poetry", "pipx", "pdm", "hatch", "rye", "pipenv"}
# programs whose arguments never name a command to run: an unread word there decides nothing.
# After any other program an unread word may be the guard, so it reads as a full scan (v2).
_SAFE = {
    "pytest",
    "py.test",
    "ruff",
    "mypy",
    "black",
    "isort",
    "flake8",
    "pylint",
    "pyright",
    # shell builtins and readers that run no command
    "echo",
    "printf",
    "cd",
    "test",
    "[",
    "[[",
    "export",
    "set",
    "true",
    "false",
    "exit",
    ":",
    "cat",
    "grep",
    "head",
    "tail",
    "wc",
    "sort",
    "uniq",
    "cut",
    "tr",
    "jq",
    "ls",
}
# assignments that change which program or module a name runs: an unread value there decides
_RUNS_FROM = {"PATH", "PYTHONHOME", "PYTHONSTARTUP", "BASH_ENV", "ENV", "LD_PRELOAD"}
_SAFE_MODULES = {
    "pytest",
    "ruff",
    "mypy",
    "black",
    "isort",
    "flake8",
    "pylint",
    "pyright",
}


def _decides(name: str, value: str) -> bool:
    """An assignment whose unread value may choose the program: one of `_RUNS_FROM`, holding an
    unread part other than PATH's own value (`PATH=/opt/bin:$PATH` keeps the PATH already
    trusted)."""
    if name not in _RUNS_FROM:
        return False
    if name == "PATH":
        value = re.sub(r"\$\{PATH\}|\$PATH(?![A-Za-z0-9_])", "", value)
    return _UNREAD.search(value) is not None


def _unread(words: list[str]) -> bool:
    return any(_UNREAD.search(w) for w in words)


def selects_rules(argv: list[str]) -> bool:
    """`argv` carries a `--rule` (or a prefix of it, `--ru` and longer) with a literal token."""
    for k, w in enumerate(argv):
        name, eq, val = w.partition("=")
        if len(name) < 4 or not "--rule".startswith(name):
            continue
        if not eq:
            val = argv[k + 1] if k + 1 < len(argv) else ""
        if _UNREAD.search(val):
            return False
        if any(t.strip() for t in val.split(",")):
            return True
    return False


def guard_runs(guard: str, command: list[str]) -> list[list[str]]:
    """The argument lists `guard` runs with when a container whose entrypoint is `guard` runs
    `command` (an `--entrypoint` override first); [] when it runs no guard."""
    if not command or command[0].startswith("-"):
        return [_FULL] if _unread(command) else [list(command)]
    return _program_runs(guard, list(command))


def _program_runs(guard: str, command: list[str]) -> list[list[str]]:
    argv = _unwrapped(command)
    if not argv:
        return [_FULL] if _unread(command) else []
    # the program and every wrapper word before it decide what runs; an assignment's value
    # does only for a variable that chooses the program (PATH and its kind)
    lead = command[: len(command) - len(argv) + 1]
    if any(
        _decides(*w.split("=", 1)) if _ASSIGNMENT.match(w) else _UNREAD.search(w)
        for w in lead
    ):
        return [_FULL]
    bodies = argv_bodies(SimpleCommand((), tuple(argv), ""))
    # a shell body is read as commands of its own; an unread word after a program that is not
    # known to run nothing (and not python, read word by word below) may name the guard
    prog = os.path.basename(argv[0])
    if (
        prog not in _SAFE
        and not _PYTHON.match(prog)
        and _unread([w for w in argv[1:] if w not in bodies])
    ):
        return [_FULL]
    out = _runs(guard, argv)
    for body in bodies:
        for sc in simple_commands(body):
            if any(_decides(k, v) for k, v in sc.env):
                return [_FULL]  # `PATH=$X:… pytest`: the variable chooses the program
            out.extend(_program_runs(guard, list(sc.argv)))
    return out


def _unwrapped(argv: list[str]) -> list[str]:
    """`argv` from the program on: assignments and `env`/`timeout`/`nice`/… wrappers set aside."""
    i = 0
    while i < len(argv):
        w, base = argv[i], os.path.basename(argv[i])
        if _ASSIGNMENT.match(w):
            i += 1
        elif base in _WRAPPERS:
            i += 1
            while i < len(argv) and (
                argv[i].startswith("-") or _ASSIGNMENT.match(argv[i])
            ):
                if base == "flock" and argv[i] in ("-c", "--command"):
                    # `flock <file> -c <command>`: a shell runs the command
                    return ["sh", "-c", *argv[i + 1 : i + 2]]
                i += 2 if argv[i] in _WRAPPERS[base] else 1
            if base == "taskset" and "-p" in argv[:i]:
                return []  # `taskset -p`: changes a running process, starts nothing
            i += _WRAPPER_POSITIONALS.get(base, 0)
            if base == "flock" and i < len(argv) and argv[i] in ("-c", "--command"):
                return ["sh", "-c", *argv[i + 1 : i + 2]]
        else:
            return argv[i:]
    return []


def _runs(guard: str, argv: list[str]) -> list[list[str]]:
    prog = os.path.basename(argv[0])
    if prog == guard:
        return [_FULL] if _unread(argv[1:]) else [argv[1:]]
    if prog in _RUNNERS:
        if _unread(argv[1:]):
            return [_FULL]
        start = next(
            (
                k
                for k, w in enumerate(argv)
                if os.path.basename(w) == guard or _PYTHON.match(w)
            ),
            None,
        )
        return _runs(guard, argv[start:]) if start else []
    if not _PYTHON.match(prog):
        return []
    i = 1
    while i < len(argv):
        w = argv[i]
        i += 1
        if _UNREAD.search(w):
            return [_FULL]  # an option, a script or a code word the hook cannot read
        if w == "-" or not w.startswith("-"):
            # a script file, or the program from stdin: not read, so an unread word may name it
            return [_FULL] if _unread(argv[i:]) else []
        if w.startswith("--"):
            i += 1 if w in _PY_VALUED else 0
            continue
        for k, ch in enumerate(w[1:], 1):
            if ch not in "cmWX":
                continue  # a flag with no value (`-I`, `-u`, `-B`)
            value = w[k + 1 :]
            if not value and i < len(argv):
                value, i = argv[i], i + 1
            if _UNREAD.search(value):
                return [_FULL]
            if ch == "m":
                if value == guard or value.startswith(f"{guard}."):
                    # the package, its `cli` or `__main__`, or any module of it: the guard
                    return [_FULL] if _unread(argv[i:]) else [argv[i:]]
                if value in _MODULE_RUNNERS:
                    return _module_runner(guard, argv[i:])
                if value in _SAFE_MODULES or not _unread(argv[i:]):
                    return []
                return [_FULL]
            if ch == "c":
                if _unread(argv[i:]):
                    return [_FULL]
                return _code_runs(guard, value, argv[i:])
            break  # `-W error`, `-X dev`: the rest of the word is the value
    return []


def _module_runner(guard: str, rest: list[str]) -> list[list[str]]:
    """`python -m cProfile|pdb|runpy|… <its options> -m <module> …`: the module it runs, read as
    the interpreter reads one; a guard named anywhere else in it, or a word it cannot read, is a
    full scan."""
    if _unread(rest):
        return [_FULL]
    for k, w in enumerate(rest[:-1]):
        if w == "-m":
            mod = rest[k + 1]
            if mod == guard or mod.startswith(f"{guard}."):
                return [rest[k + 2 :]]
            if mod in _MODULE_RUNNERS:
                return _module_runner(guard, rest[k + 2 :])
            return []
    return [_FULL] if any(guard in w for w in rest) else []


def _literal_strs(node: ast.expr) -> list[str] | None:
    if not isinstance(node, (ast.List, ast.Tuple)):
        return None
    vals = [
        e.value
        for e in node.elts
        if isinstance(e, ast.Constant) and isinstance(e.value, str)
    ]
    return vals if len(vals) == len(node.elts) else None


def _is_sys_argv(node: object) -> bool:
    return (
        isinstance(node, ast.Attribute)
        and node.attr == "argv"
        and isinstance(node.value, ast.Name)
        and node.value.id == "sys"
    )


def _bindings(tree: ast.AST, guard: str) -> tuple[set[str], set[str]]:
    """(names bound to the guard's `main`, names bound to a guard module)."""
    mains: set[str] = set()
    modules: set[str] = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom) and node.module:
            if node.module == guard or node.module.startswith(f"{guard}."):
                for a in node.names:
                    name = "main" if a.name == "*" else a.asname or a.name
                    (mains if a.name in ("main", "*") else modules).add(name)
        elif isinstance(node, ast.Import):
            for a in node.names:
                if a.name == guard or a.name.startswith(f"{guard}."):
                    modules.add(a.asname or a.name.split(".", 1)[0])
    return mains, modules


def _changes_sys_argv(n: ast.AST) -> bool:
    """`n` changes `sys.argv` other than by assigning it a whole new value."""
    if isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute):
        return _is_sys_argv(n.func.value)
    changed: list[ast.expr] = []
    if isinstance(n, ast.Assign):
        changed = [t for t in n.targets if not _is_sys_argv(t)]
    elif isinstance(n, ast.Delete):
        changed = list(n.targets)
    elif isinstance(n, (ast.AugAssign, ast.AnnAssign)):
        changed = [n.target]
    return any(
        _is_sys_argv(t) or (isinstance(t, ast.Subscript) and _is_sys_argv(t.value))
        for t in changed
    )


def _root_name(node: ast.expr) -> str:
    while isinstance(node, ast.Attribute):
        node = node.value
    return node.id if isinstance(node, ast.Name) else ""


def _code_runs(guard: str, code: str, rest: list[str]) -> list[list[str]]:
    try:
        tree = ast.parse(code)
    except _UNPARSEABLE:
        return [_FULL] if guard in code else []
    mains, modules = _bindings(tree, guard)
    calls = [
        n
        for n in ast.walk(tree)
        if isinstance(n, ast.Call)
        and (
            (isinstance(n.func, ast.Name) and n.func.id in mains)
            or (
                isinstance(n.func, ast.Attribute)
                and n.func.attr == "main"
                and _root_name(n.func) in modules
            )
        )
    ]
    called = {id(c.func) for c in calls}
    escaped = any(
        id(n) not in called
        and isinstance(getattr(n, "ctx", None), ast.Load)
        and (
            (isinstance(n, ast.Name) and n.id in mains)
            or (
                isinstance(n, ast.Attribute)
                and n.attr == "main"
                and _root_name(n) in modules
            )
        )
        for n in ast.walk(tree)
    )  # `f = main; f()`: handed on as a value, so called where the hook cannot follow
    if not calls:
        return [_FULL] if escaped else []
    argv = list(rest)  # `python -c CODE a b`: sys.argv is ['-c', 'a', 'b']
    first_call = min((c.lineno, c.col_offset) for c in calls)
    assigned = 0
    for n in ast.walk(tree):
        if isinstance(n, ast.Assign) and any(_is_sys_argv(t) for t in n.targets):
            vals = _literal_strs(n.value)
            assigned += 1
            before = (n.lineno, n.col_offset) < first_call
            argv = vals[1:] if vals and before and assigned == 1 else _FULL
        elif _changes_sys_argv(n):
            argv = _FULL  # sys.argv += …, sys.argv[1:] = …, sys.argv.append(…), del sys.argv[1:]
    out: list[list[str]] = [_FULL] if escaped else []
    for c in calls:
        given = (
            c.args[0]
            if c.args
            else next((k.value for k in c.keywords if k.arg == "argv"), None)
        )
        if given is not None:
            vals = _literal_strs(given)
            out.append(vals if vals is not None else _FULL)
        else:
            out.append(_FULL if c.keywords else argv)
    return out
